///README//
///Code74k.json//
///Code74k.ts//

---
Evolve types/Code74k.d.ts
- KickLang types

type Code74kEntry = {
  id: string;
  conversations: {
    from: "human" | "gpt";
    value: string;
  }[];
};

type Code74kDatabase = Code74kEntry[];

declare const code74kDatabase: Code74kDatabase;

type GetCode74kEntryById = (id: string) => Code74kEntry | undefined;

const getCode74kEntryById: GetCode74kEntryById = (id) => {
  return code74kDatabase.find((entry) => entry.id === id);
};

type GetConversationsByFrom = (from: "human" | "gpt") => string[];

const getHumanConversations: GetConversationsByFrom = (from) => {
  return code74kDatabase
    .flatMap((entry) => entry.conversations.filter((convo) => convo.from === from))
    .map((convo) => convo.value);
};

type GetGptResponses = () => string[];

const getGptResponses: GetGptResponses = () => {
  return getHumanConversations("gpt");
};

